/* American staples: breakfast, lunch, and dinner. Same fields as recipes.js, plus:
   `byo` (build your own): a basic recipe with `ideas` for changing it to whatever you have.
   `choose`: ways to cook it (like egg doneness). A step with `by` takes its timer from `mins`,
   one per option of that choice; its `min` is the timer for the default (`pick`) option. */
RECIPES.push(
 {id:"boiled-eggs",title:"Boiled Eggs Your Way",cuisine:"American",diet:["vegetarian","halal","glutenfree"],serves:2,cost:0.75,meal:["breakfast","snack"],tags:["eggs"],
  desc:"Eggs cooked in their shells in boiling water, from soft with a runny yolk to fully hard-boiled. Pick how you like them and the timer matches. Great for breakfast, salads, or a grab-and-go snack.",
  pantry:["eggs","salt"],
  ingredients:["4 large eggs, straight from the fridge","Water, enough to cover the eggs by 2 cm (1 in)","A big bowl of ice water","Salt and pepper, to serve"],
  choose:[{id:"doneness",label:"How do you like your eggs?",pick:1,options:[
   {label:"Soft",undercooked:true,note:"runny yolk and just-set white. Eat with a spoon from the shell, or dip toast in it."},
   {label:"Jammy",undercooked:true,note:"thick, sticky, deep orange yolk. Great on toast, ramen, or salads."},
   {label:"Medium",note:"yolk mostly set with a soft, slightly fudgy center."},
   {label:"Hard",note:"fully set, pale yellow yolk. Best for egg salad, deviled eggs, and snacks."}]}],
  steps:[
   {name:"Boil the water",desc:"Fill a medium pot with enough water to cover 4 eggs by 2 cm (1 in) and bring it to a full rolling boil over high heat. Fill a bowl with ice and cold water while you wait.",min:8},
   {name:"Cook the eggs",desc:"Turn the heat down to medium so the water bubbles gently. Use a spoon to lower the cold eggs into the water one at a time so they don't crack. Start the timer as soon as the last egg goes in.",min:7,by:"doneness",mins:[6,7,9,12]},
   {name:"Ice bath",desc:"Move the eggs straight into the ice water with the spoon. This stops the cooking so they don't go past the doneness you picked, and makes them easier to peel.",min:5},
   {name:"Peel and serve",desc:"Tap each egg all over on the counter, then peel under a thin stream of water, starting at the wide end. Season with salt and pepper. Unpeeled boiled eggs keep 1 week in the fridge.",min:3,timer:false}]},
 {id:"diner-breakfast",title:"Diner Breakfast: Eggs, Home Fries, and Toast",cuisine:"American",diet:["vegetarian","halal"],serves:2,cost:1.25,meal:["breakfast"],tags:["eggs","fried"],
  desc:"The classic American diner plate: crispy pan-fried potatoes with onion, fried eggs cooked the way you like them, and buttered toast. Hearty, cheap, and made in one skillet.",
  pantry:["potatoes","onion","eggs","butter","bread","paprika"],
  ingredients:["2 medium potatoes (about 400 g / 14 oz), cut into 2 cm (¾ in) cubes","½ onion, diced","3 tbsp oil, divided","½ tsp paprika","½ tsp salt, plus more for the eggs","¼ tsp black pepper","4 eggs","1 tbsp butter","4 slices bread, for toast","Ketchup or hot sauce, to serve"],
  choose:[{id:"eggs",label:"How do you like your fried eggs?",pick:1,options:[
   {label:"Sunny side up",undercooked:true,note:"never flipped. Set white with a bright, runny yolk on top."},
   {label:"Over easy",undercooked:true,note:"flipped for a moment. White fully set, yolk still runny."},
   {label:"Over medium",undercooked:true,note:"flipped and cooked a little longer. Yolk thick and jammy."},
   {label:"Over hard",note:"flipped and cooked until the yolk is fully set."}]}],
  steps:[
   {name:"Soften the potatoes",desc:"Put the potato cubes in a microwave-safe bowl with 2 tbsp water, cover with a plate, and microwave 5 min until just tender. (No microwave? Boil them 6 min, then drain.) This makes the home fries fast and soft inside.",min:5},
   {name:"Fry the potatoes",desc:"Heat 2 tbsp oil in a large skillet over medium-high heat. Add the potatoes in one layer and leave them alone 4 min so they brown. Add the onion, paprika, ½ tsp salt, and pepper, and cook 8 min more, stirring every couple of minutes, until crispy and golden. Move them to plates.",min:12},
   {name:"Fry the eggs",desc:"Lower the heat to medium. Add 1 tbsp oil and the butter to the same pan. Crack in the eggs and sprinkle with salt. Cook until the whites are set. For over easy, medium, or hard: slide a spatula under each egg and flip it once near the end. Start the toast now.",min:4,by:"eggs",mins:[3,4,5,6]},
   {name:"Toast and serve",desc:"Butter the toast and plate it with the eggs and home fries. Serve with ketchup or hot sauce.",min:2,timer:false}]},
 {id:"french-toast",title:"Cinnamon French Toast",cuisine:"American",diet:["vegetarian","halal"],serves:3,cost:0.75,meal:["breakfast"],tags:["pancakes"],
  desc:"Thick slices of bread soaked in a cinnamon-vanilla egg custard and pan-fried in butter until golden outside and soft like bread pudding inside. Served with maple syrup and fruit. A great use for slightly stale bread.",
  pantry:["bread","eggs","milk","cinnamon","vanilla","butter","maple syrup"],
  ingredients:["6 thick slices bread (a day or two old is best)","3 eggs","¾ cup (180 ml) milk","1 tbsp sugar","1 tsp ground cinnamon","1 tsp vanilla extract","Pinch of salt","2 tbsp butter, divided","Maple syrup and berries or banana slices, to serve"],
  steps:[
   {name:"Make the custard",desc:"In a wide, shallow dish, whisk the eggs, milk, sugar, cinnamon, vanilla, and salt until no streaks of egg remain.",min:3,timer:false},
   {name:"Heat the pan",desc:"Heat a large nonstick skillet over medium heat. Add 1 tbsp butter and let it melt and foam.",min:2,timer:false},
   {name:"Soak and cook the first batch",desc:"Dip 3 slices into the custard, about 10 seconds per side, so they soak through but don't fall apart. Let the extra drip off and lay them in the pan. Cook 3 min per side until deep golden brown.",min:6},
   {name:"Cook the second batch",desc:"Add the rest of the butter and repeat with the last 3 slices. Keep the first batch warm on a plate covered with a clean towel.",min:6},
   {name:"Serve",desc:"Serve warm with maple syrup and fruit.",min:1,timer:false}]},
 {id:"breakfast-burritos",title:"Build-Your-Own Breakfast Burritos",cuisine:"American",diet:["vegetarian","halal"],serves:4,cost:1.50,meal:["breakfast"],tags:["wrap","eggs"],
  desc:"Big flour tortillas wrapped around soft scrambled eggs, crispy potatoes, cheese, and salsa. The base recipe is simple, and you can fill them with whatever you have. They also freeze well for busy mornings.",
  pantry:["tortillas","eggs","potatoes","cheese","salsa","onion"],
  ingredients:["4 large flour tortillas","6 eggs","2 tbsp milk","1 medium potato, cut into 1 cm (½ in) cubes","½ onion, diced","2 tbsp oil","½ tsp salt","¼ tsp pepper","1 cup (100 g) shredded cheddar cheese","½ cup salsa"],
  byo:{intro:"The eggs, tortilla, and cheese are the base. Swap or add anything below, and cook raw meat or vegetables in step 2 with the potatoes.",ideas:[
   ["Proteins","Cooked breakfast sausage (turkey or beef keeps it halal), black beans, leftover taco meat, crumbled tofu instead of eggs."],
   ["Vegetables","Bell pepper, spinach (stir in at the end), mushrooms, jalapeño, leftover roasted vegetables."],
   ["Sauces","Salsa verde, hot sauce, sour cream, guacamole."],
   ["Techniques","Toast the rolled burrito seam-side down in a dry pan 1–2 min so it stays closed. To freeze: wrap each in foil, then reheat in the oven at 350°F (175°C) for 25 min."]]},
  steps:[
   {name:"Prep",desc:"Cube the potato and dice the onion. Whisk the eggs with the milk, salt, and pepper. Get out any extra fillings you're adding.",min:5,timer:false},
   {name:"Cook the potatoes",desc:"Heat the oil in a large nonstick skillet over medium heat. Add the potato and onion (and any raw meat or vegetables) and cook, stirring now and then, until the potatoes are golden and tender, about 10 min.",min:10},
   {name:"Scramble the eggs",desc:"Lower the heat to medium-low and pour the eggs over the potatoes. Stir slowly with a spatula until the eggs are softly set but still look a little wet. They finish cooking inside the burrito.",min:3,timer:false},
   {name:"Warm the tortillas",desc:"Warm each tortilla 20 seconds in a dry pan or 15 seconds in the microwave so it bends without tearing.",min:2,timer:false},
   {name:"Fill and roll",desc:"Put a quarter of the filling in a line just below the middle of each tortilla. Top with cheese and salsa. Fold in the sides, then roll it up tightly from the bottom.",min:4,timer:false}]},
 {id:"byo-oatmeal",title:"Build-Your-Own Oatmeal",cuisine:"American",diet:["vegan","vegetarian","halal"],serves:2,cost:0.50,meal:["breakfast"],tags:["bowl"],
  desc:"A warm bowl of creamy oats cooked on the stove, topped with whatever you like: fruit, nut butter, cinnamon, or a savory egg. Tell the app which oats you have and the timer matches. One of the cheapest filling breakfasts there is.",
  pantry:["oats","cinnamon","banana","peanut butter","brown sugar"],
  ingredients:["1 cup oats (rolled, quick, or steel-cut; steel-cut needs 3 cups liquid)","2 cups (480 ml) water or plant milk (or dairy milk if it doesn't need to be vegan)","Pinch of salt","½ tsp ground cinnamon","1 tbsp brown sugar or maple syrup, or to taste","Toppings (see ideas)"],
  choose:[{id:"oats",label:"Which oats do you have?",pick:1,options:[
   {label:"Quick oats",note:"thin, small flakes. Ready in about 2 minutes, very soft."},
   {label:"Rolled oats",note:"also called old-fashioned. Creamy with a little chew."},
   {label:"Steel-cut oats",note:"chopped whole oats. Nutty and chewy. Use 3 cups of liquid instead of 2."}]}],
  byo:{intro:"Plain oats are a blank canvas. Mix and match toppings, sweet or savory.",ideas:[
   ["Fruit","Sliced banana, berries (frozen work great; stir them in while it cooks), chopped apple, raisins."],
   ["Protein","Peanut or almond butter, a spoon of yogurt, nuts or seeds, or for savory: a fried egg, soy sauce, and green onion."],
   ["Flavors","Cocoa powder, vanilla, pumpkin pie spice, jam, a pinch of salt and a spoon of butter."],
   ["Techniques","Toast the dry oats in the pot for 2 min first for a nuttier taste. Make a big batch of steel-cut oats and reheat portions with a splash of water all week."]]},
  steps:[
   {name:"Bring the liquid to a boil",desc:"Put the water or milk and the salt in a small pot over medium-high heat and bring it to a boil. Watch milk closely so it doesn't boil over.",min:4,timer:false},
   {name:"Cook the oats",desc:"Stir in the oats and cinnamon and turn the heat down to low. Cook uncovered, stirring every couple of minutes so the bottom doesn't stick, until thick and creamy.",min:5,by:"oats",mins:[2,5,25]},
   {name:"Rest and top",desc:"Take the pot off the heat, stir in the sugar or syrup, and let it sit 2 min to thicken. Spoon into bowls and add your toppings.",min:2,timer:false}]},
 {id:"breakfast-sandwich",title:"Build-Your-Own Breakfast Sandwich",cuisine:"American",diet:["vegetarian","halal"],serves:2,cost:1.25,meal:["breakfast"],tags:["sandwich","eggs"],
  desc:"A drive-through-style breakfast sandwich made at home: a fluffy folded egg and melted cheese on a toasted English muffin. Add a breakfast meat or vegetables to make it your own. Faster than the drive-through and much cheaper.",
  pantry:["english muffins","eggs","cheese","butter"],
  ingredients:["2 English muffins (or bagels, biscuits, or toast)","3 eggs","1 tbsp milk","Pinch of salt and pepper","1 tbsp butter","2 slices American or cheddar cheese"],
  byo:{intro:"Egg, cheese, and bread are the base. Add anything below.",ideas:[
   ["Meats","Turkey or beef bacon, a breakfast sausage patty, sliced deli ham (pork), or leftover steak. Cook raw meat in the pan before the egg."],
   ["Extras","Sliced tomato, spinach, avocado, hot sauce, pepper jelly, a smear of mayo or ketchup."],
   ["Breads","Bagel, biscuit, croissant, toast, or a tortilla folded around everything."],
   ["Techniques","Make it ahead: wrap cooled sandwiches in foil and freeze. Microwave from frozen 1–1½ min (unwrap the foil first)."]]},
  steps:[
   {name:"Toast the bread",desc:"Split and toast the English muffins. Cook any breakfast meat in a nonstick skillet now and set it aside.",min:4,timer:false},
   {name:"Cook a folded egg",desc:"Whisk the eggs, milk, salt, and pepper. Melt the butter in the skillet over medium-low heat and pour in the eggs. When the edges set (about 1 min), push them toward the middle and tilt the pan so raw egg runs underneath. When almost set, fold it like a letter into a square and cut in half.",min:3,timer:false},
   {name:"Melt the cheese",desc:"Lay a slice of cheese on each egg half, cover the pan, and turn off the heat for 1 min so the cheese melts.",min:1,timer:false},
   {name:"Build",desc:"Stack the egg and cheese on the muffin bottoms with any meat and extras, and close with the tops.",min:2,timer:false}]},
 {id:"byo-sandwich",title:"Build-Your-Own Deli Sandwich",cuisine:"American",diet:["halal"],serves:2,cost:2.00,meal:["lunch"],tags:["sandwich"],
  desc:"A tall, satisfying deli-style sandwich built the way sandwich shops do it: spread on both slices, meat and cheese in the middle, crisp vegetables on top, and nothing soggy. Use the base recipe or swap in whatever's in your fridge.",
  pantry:["bread","deli turkey","cheese","lettuce","tomato","mayonnaise","mustard"],
  ingredients:["4 slices sandwich bread, or 2 sub rolls","2 tbsp mayonnaise","1 tbsp mustard","170 g (6 oz) sliced deli turkey or chicken (halal-certified to keep it halal)","4 slices provolone, Swiss, or cheddar cheese","2 lettuce leaves","1 tomato, thinly sliced","¼ red onion, thinly sliced","Salt and pepper"],
  byo:{intro:"Any sandwich is bread + spread + filling + crunch. Pick one or more from each group.",ideas:[
   ["Fillings","Deli turkey, chicken, roast beef, or ham (pork); tuna or chicken salad; leftover roast meat; hummus and roasted vegetables; sliced hard-boiled egg."],
   ["Spreads","Mayo, mustard, pesto, hummus, cream cheese, ranch, or mashed avocado."],
   ["Crunch","Lettuce, cucumber, pickles, banana peppers, sprouts, potato chips tucked inside."],
   ["Techniques","Spread both slices edge to edge so wet fillings don't soak the bread. Salt and pepper the tomato. Put lettuce between tomato and bread. Toast it, or press it in a hot pan under a heavy pot 2–3 min per side for a melty panini."]]},
  steps:[
   {name:"Prep the vegetables",desc:"Wash and dry the lettuce. Slice the tomato and onion thinly. Pat the tomato slices dry with a paper towel and sprinkle with a little salt and pepper.",min:4,timer:false},
   {name:"Spread",desc:"Toast the bread if you like. Spread mayo on one slice and mustard on the other, all the way to the edges.",min:2,timer:false},
   {name:"Layer",desc:"On the bottom slice, layer the cheese, then the meat (fold the slices loosely so the sandwich is tall and tender), then the tomato and onion, then the lettuce. Close the sandwich.",min:3,timer:false},
   {name:"Cut and serve",desc:"Press down gently, then cut it in half diagonally with a sharp knife. Wrap tightly in foil or wax paper if you're packing it for later.",min:1,timer:false}]},
 {id:"grilled-cheese",title:"Grilled Cheese, Any Way",cuisine:"American",diet:["vegetarian","halal"],serves:2,cost:0.75,meal:["lunch"],tags:["sandwich"],
  desc:"Buttered bread toasted golden and crisp in a pan around a thick layer of melted cheese. The classic partner for tomato soup, and easy to dress up with add-ins.",
  pantry:["bread","cheese","butter"],
  ingredients:["4 slices bread","2 tbsp soft butter (or mayonnaise, which browns evenly)","4 slices cheddar or American cheese, or 1 cup (100 g) shredded"],
  byo:{intro:"Bread, butter, and cheese are all you need. To make it a \"melt,\" add one or two of these inside.",ideas:[
   ["Cheeses","Mix two: cheddar with mozzarella for stretch, pepper jack for heat, Swiss, gouda, or a spoon of cream cheese."],
   ["Add-ins","Sliced tomato, caramelized onion, jalapeño, pickles, spinach, sliced apple, or leftover chicken. Keep add-ins thin so the cheese can melt."],
   ["Breads","Sourdough, rye, Texas toast, or a split bagel."],
   ["Techniques","Cook it low and slow with a lid on for the first side so the cheese melts before the bread burns."]]},
  steps:[
   {name:"Butter the bread",desc:"Spread butter on one side of each slice, all the way to the edges.",min:2,timer:false},
   {name:"Build",desc:"Heat a skillet over medium-low heat. Put 2 slices in the pan butter-side down, top with cheese and any add-ins, then close with the other slices, butter-side up.",min:2,timer:false},
   {name:"Cook the first side",desc:"Cover the pan and cook until the bottom is deep golden and the cheese starts to melt, about 3–4 min. Don't turn the heat up; it burns fast.",min:4,timer:false},
   {name:"Flip and finish",desc:"Flip with a spatula and cook uncovered until the second side is golden and the cheese is fully melted, about 3 min. Rest 1 min before cutting, so the cheese doesn't all run out.",min:4,timer:false}]},
 {id:"tuna-melt",title:"Tuna Melt",cuisine:"American",diet:["halal"],seafood:true,serves:2,cost:1.50,meal:["lunch"],tags:["sandwich"],
  desc:"A diner favorite: creamy tuna salad with celery and a little mustard, topped with melted cheddar on toasted bread. A cheap, filling lunch made from a can of tuna.",
  pantry:["canned tuna","mayonnaise","celery","mustard","bread","cheese","lemon"],
  ingredients:["1 can (140 g / 5 oz) tuna, drained well","3 tbsp mayonnaise","1 celery stalk, finely diced","1 tbsp minced red onion or pickle","1 tsp mustard","1 tsp lemon juice","Pinch of salt and pepper","4 slices bread","1 tbsp butter","4 slices cheddar cheese"],
  steps:[
   {name:"Make the tuna salad",desc:"In a bowl, mix the tuna, mayonnaise, celery, onion or pickle, mustard, lemon juice, salt, and pepper with a fork, breaking up big chunks.",min:4,timer:false},
   {name:"Build the sandwiches",desc:"Butter one side of each slice of bread. Put 2 slices butter-side down on a board, top each with a slice of cheese, half the tuna, another slice of cheese, then the other bread, butter-side up.",min:3,timer:false},
   {name:"Cook",desc:"Cook in a covered skillet over medium-low heat until golden and the cheese melts, about 4 min per side.",min:8,timer:false},
   {name:"Serve",desc:"Cut in half and serve hot with pickles or chips.",min:1,timer:false}]},
 {id:"byo-salad",title:"Build-Your-Own Big Salad",cuisine:"American",diet:["vegan","vegetarian","halal","glutenfree"],serves:2,cost:2.00,meal:["lunch","dinner"],tags:["salad"],
  desc:"A big, filling meal salad with a simple homemade vinaigrette. The recipe teaches the formula (greens, something crunchy, something hearty, a protein, a dressing) so you can build one from whatever's in your fridge.",
  pantry:["lettuce","cucumber","tomato","chickpeas","olive oil","vinegar","mustard"],
  ingredients:["1 large head romaine or 150 g (5 oz) salad greens","1 cucumber","1 cup cherry tomatoes","1 carrot","1 can (400 g / 15 oz) chickpeas, drained and rinsed","Dressing: 3 tbsp olive oil, 1 tbsp vinegar or lemon juice, 1 tsp mustard, 1 tsp maple syrup or honey, ¼ tsp salt, pinch of pepper"],
  byo:{intro:"A filling salad has five parts. Pick at least one from each.",ideas:[
   ["Greens","Romaine, spinach, mixed greens, shredded cabbage (cheap and lasts for weeks)."],
   ["Protein","Chickpeas, black beans, boiled eggs, canned tuna, leftover chicken or steak, tofu, cheese."],
   ["Hearty","Leftover rice or pasta, roasted sweet potato, corn, avocado, croutons."],
   ["Crunch","Nuts, seeds, tortilla chips, sliced radish or apple."],
   ["Dressings","Swap the vinegar for lemon or lime; add garlic, herbs, soy sauce, or a spoon of yogurt for a creamy dressing. Ranch, Caesar, or Italian from a bottle are fine too."],
   ["Techniques","Dry the greens well so dressing sticks. Salt the tomatoes and cucumbers. Dress and toss right before eating so it stays crisp."]]},
  steps:[
   {name:"Make the dressing",desc:"Put all the dressing ingredients in a jar, close the lid, and shake hard until creamy. Taste: add a pinch of salt if it's flat, or a drop of syrup if it's too sour.",min:3,timer:false},
   {name:"Prep the greens",desc:"Chop the romaine into bite-size pieces, wash it, and dry it well in a salad spinner or by rolling it gently in a clean towel.",min:5,timer:false},
   {name:"Chop the toppings",desc:"Slice the cucumber, halve the tomatoes, and grate or thinly slice the carrot. Drain and rinse the chickpeas, then pat them dry.",min:6,timer:false},
   {name:"Toss and serve",desc:"Put the greens in a big bowl, add the toppings, and drizzle with most of the dressing. Toss with your hands or tongs until everything is lightly coated, adding more dressing if needed.",min:2,timer:false}]},
 {id:"sloppy-joes",title:"Sloppy Joes",cuisine:"American",diet:["halal"],serves:4,cost:1.75,meal:["lunch","dinner"],tags:["sandwich"],
  desc:"Ground beef simmered in a sweet and tangy tomato sauce with onion and peppers, piled onto soft toasted buns. Messy, kid-friendly, and ready in about 25 minutes.",
  pantry:["ground beef","onion","bell pepper","garlic","ketchup","tomato paste","mustard","soy sauce","buns"],
  ingredients:["450 g (1 lb) ground beef (halal-certified to keep it halal)","1 onion, finely diced","½ green bell pepper, finely diced","2 garlic cloves, minced","¾ cup ketchup","2 tbsp tomato paste","1 tbsp brown sugar","1 tbsp yellow mustard","1 tbsp soy sauce (most Worcestershire sauce contains anchovy and a little alcohol vinegar)","½ cup (120 ml) water","½ tsp salt","4 hamburger buns"],
  steps:[
   {name:"Brown the beef",desc:"In a large skillet over medium-high heat, cook the beef, breaking it into small crumbles with a spoon, until no pink remains, about 6 min. Spoon off most of the fat.",min:6},
   {name:"Cook the vegetables",desc:"Add the onion and pepper and cook 4 min until soft. Add the garlic for 30 seconds.",min:5},
   {name:"Simmer the sauce",desc:"Stir in the ketchup, tomato paste, brown sugar, mustard, soy sauce, water, and salt. Simmer on medium-low, stirring now and then, until thick enough to mound on a spoon, about 10 min.",min:10},
   {name:"Toast the buns and serve",desc:"Toast the cut sides of the buns in a dry pan or under the broiler. Pile on the filling and serve with pickles.",min:3,timer:false}]},
 {id:"steak-your-way",title:"Pan-Seared Steak Your Way",cuisine:"American",diet:["halal","glutenfree"],serves:2,cost:6.00,meal:["dinner"],tags:["grill"],
  desc:"A thick steak seared hard in a hot pan for a deep brown crust, then basted with butter, garlic, and herbs. Choose how done you like it and each side's timer matches. A steakhouse dinner at home.",
  pantry:["steak","butter","garlic","thyme","salt","pepper"],
  ingredients:["2 boneless steaks, about 2.5 cm (1 in) thick (ribeye, strip, or sirloin; halal-certified to keep it halal)","1 tsp kosher salt","½ tsp black pepper","1 tbsp high-heat oil (vegetable, canola, or avocado)","2 tbsp butter","3 garlic cloves, smashed","2 sprigs fresh thyme or rosemary (or ½ tsp dried)"],
  choose:[{id:"doneness",label:"How do you like your steak?",pick:1,options:[
   {label:"Rare",undercooked:true,note:"cool red center, 120–125°F (49–52°C) inside. Feels soft and squishy when you press the middle."},
   {label:"Medium rare",undercooked:true,note:"warm red-pink center, 130–135°F (54–57°C). Feels soft but springs back a little. The steakhouse favorite."},
   {label:"Medium",note:"warm pink center, 135–145°F (57–63°C). Springs back and feels slightly firm."},
   {label:"Medium well",note:"a little pink in the very middle, 145–155°F (63–68°C). Feels firm with a little give."},
   {label:"Well done",note:"no pink, 155°F+ (68°C+). Feels firm all over. It's normal for it to be firmer; the butter baste keeps it juicy."}]}],
  byo:{intro:"The method works for any steak. Change up the seasoning and the sauce.",ideas:[
   ["Cuts","Ribeye (rich, marbled), strip (beefy), sirloin (cheaper, leaner), flank or skirt (thin: cook 2–3 min per side and slice thinly across the grain)."],
   ["Seasoning","Salt and pepper is classic. Or try garlic powder and smoked paprika, Montreal steak seasoning, or a coffee rub."],
   ["Sauces","Chimichurri, steak sauce, garlic-herb butter, creamy peppercorn, or blue cheese."],
   ["Techniques","Use a meat thermometer for perfect results; pull the steak about 5°F before your target, since it rises while it rests. Thicker steak? Sear both sides, then finish in a 400°F (200°C) oven."]]},
  steps:[
   {name:"Dry and season",desc:"Take the steaks out of the fridge 20–30 min before cooking if you can. Pat them very dry with paper towels (a dry surface browns better) and season all over with the salt and pepper.",min:3,timer:false},
   {name:"Heat the pan",desc:"Heat a heavy skillet (cast iron is best) over high heat until very hot, about 3 min. Add the oil; it should shimmer and just start to smoke. Turn on your fan.",min:3,timer:false},
   {name:"Sear the first side",desc:"Lay the steaks in the pan, away from you. Don't move them; this builds the crust.",min:3,by:"doneness",mins:[2,3,4,5,6]},
   {name:"Flip and baste",desc:"Flip the steaks. Turn the heat to medium and add the butter, garlic, and herbs. When the butter foams, tilt the pan and spoon the butter over the steaks again and again. No thermometer? Press the center and compare with the feel described above, or cut a small slit in the middle to check the color.",min:3,by:"doneness",mins:[2,3,4,5,6]},
   {name:"Rest",desc:"Move the steaks to a cutting board and rest 5 min so the juices settle instead of running out. Slice across the grain and spoon the pan butter over the top.",min:5}]},
 {id:"burgers-your-way",title:"Build-Your-Own Smash Burgers",cuisine:"American",diet:["halal"],serves:4,cost:2.75,meal:["dinner","lunch"],tags:["sandwich","grill"],
  desc:"Diner-style burgers: balls of ground beef smashed thin on a very hot pan for crispy, browned edges, topped with melty cheese on a toasted bun. Pick your doneness and stack on your favorite toppings.",
  pantry:["ground beef","buns","cheese","lettuce","tomato","onion","pickles","ketchup","mustard"],
  ingredients:["680 g (1½ lb) ground beef, 80/20 (halal-certified to keep it halal)","1 tsp salt","½ tsp black pepper","4 slices American or cheddar cheese","4 burger buns","1 tbsp butter, for the buns","Toppings: lettuce, sliced tomato, sliced onion, pickles, ketchup, mustard"],
  choose:[{id:"doneness",label:"How do you like your burger?",pick:2,options:[
   {label:"Medium",undercooked:true,note:"a little pink inside, about 140°F (60°C)."},
   {label:"Medium well",undercooked:true,note:"just a trace of pink, about 150°F (66°C)."},
   {label:"Well done",note:"no pink, 160°F (71°C), the temperature recommended for ground meat. Still juicy because smash burgers cook fast."}]}],
  byo:{intro:"The beef and bun are the base. Make it yours with any of these.",ideas:[
   ["Patties","Ground turkey or chicken (always cook to well done), or a store-bought veggie or bean patty for a vegetarian burger."],
   ["Toppings","Caramelized or grilled onions, sautéed mushrooms, jalapeños, avocado, a fried egg, beef bacon, coleslaw."],
   ["Sauces","Burger sauce (mix 3 tbsp mayo, 1 tbsp ketchup, 1 tbsp chopped pickle), BBQ sauce, sriracha mayo, ranch."],
   ["Techniques","Don't press the burger after the first smash, or the juices run out. For a thick grilled burger, make 2 cm (¾ in) patties and grill over medium-high 4–6 min per side."]]},
  steps:[
   {name:"Prep",desc:"Divide the beef into 4 loose balls; don't pack them tight. Slice the toppings. Butter the cut sides of the buns.",min:5,timer:false},
   {name:"Toast the buns",desc:"Heat a large heavy skillet over medium heat and toast the buns cut-side down until golden, about 1 min. Set them aside. Turn the heat to high.",min:3,timer:false},
   {name:"Smash and sear",desc:"Once the pan is very hot, put 2 balls in (cook in 2 batches if the pan is small). Press each flat with a sturdy spatula to about 1 cm (½ in) thick, holding 10 seconds. Season with half the salt and pepper. Don't move them until the edges are deep brown and crispy.",min:3,by:"doneness",mins:[2,3,3]},
   {name:"Flip and add cheese",desc:"Scrape under each patty with the spatula to keep the crust, and flip. Season, add a slice of cheese, and cook until the cheese melts.",min:3,by:"doneness",mins:[1,2,3]},
   {name:"Build",desc:"Put each patty on a bun and add your toppings and sauce. Cook the second batch the same way.",min:3,timer:false}]},
 {id:"meatloaf",title:"Glazed Meatloaf with Mashed Potatoes",cuisine:"American",diet:["halal"],serves:6,cost:2.25,meal:["dinner"],tags:["oven"],
  desc:"A tender loaf of seasoned ground beef baked with a sweet, tangy ketchup glaze, served with creamy mashed potatoes. Classic Sunday comfort food, and the leftovers make great sandwiches.",
  pantry:["ground beef","breadcrumbs","eggs","milk","onion","garlic","ketchup","brown sugar","vinegar","potatoes","butter"],
  ingredients:["900 g (2 lb) ground beef (halal-certified to keep it halal)","1 cup (60 g) breadcrumbs or 3 slices bread, torn small","½ cup (120 ml) milk","2 eggs","1 onion, finely grated or minced","2 garlic cloves, minced","1½ tsp salt, divided","½ tsp pepper","1 tsp dried thyme or Italian seasoning","Glaze: ½ cup ketchup, 2 tbsp brown sugar, 1 tbsp vinegar","1.2 kg (2½ lb) potatoes, peeled and cut into large chunks","4 tbsp butter","½ cup (120 ml) warm milk, for the potatoes"],
  steps:[
   {name:"Mix the meatloaf",desc:"Heat the oven to 375°F (190°C). In a large bowl, soak the breadcrumbs in ½ cup milk for 2 min. Add the eggs, onion, garlic, 1 tsp salt, pepper, and thyme and stir. Add the beef and mix gently with your hands until just combined; overmixing makes it tough.",min:7,timer:false},
   {name:"Shape and glaze",desc:"Shape into a loaf about 23 × 12 cm (9 × 5 in) on a foil-lined sheet pan. Stir the glaze ingredients together and spread half over the top.",min:3,timer:false},
   {name:"Bake",desc:"Bake 40 min. Meanwhile, put the potatoes in a pot of cold salted water, bring to a boil, and simmer until a fork slides in easily, about 15–20 min.",min:40},
   {name:"Glaze again",desc:"Brush the rest of the glaze on the meatloaf and bake 15 min more, until it reads 160°F (71°C) in the middle. No thermometer? The juices should run clear and the center should show no pink when you cut into it. Meanwhile, drain the potatoes and mash them with the butter, warm milk, and ½ tsp salt.",min:15},
   {name:"Rest and slice",desc:"Rest the meatloaf 10 min so it holds together, then slice thickly and serve with the mashed potatoes.",min:10}]},
 {id:"pot-roast",title:"Big-Pot Pot Roast",cuisine:"American",diet:["halal"],serves:6,cost:3.75,meal:["dinner"],tags:["stew","onepot","oven"],
  desc:"A family-style Sunday dinner: a beef chuck roast browned and slowly braised in broth with onions, carrots, and potatoes until it falls apart with a fork, with the juices made into gravy. Mostly hands-off, and you can use whatever root vegetables you have.",
  pantry:["beef chuck roast","onion","carrots","potatoes","garlic","tomato paste","broth","thyme","bay leaves","flour"],
  ingredients:["1.4 kg (3 lb) beef chuck roast (halal-certified to keep it halal)","2 tsp salt","1 tsp pepper","2 tbsp oil","2 onions, cut into wedges","4 garlic cloves, smashed","2 tbsp tomato paste","3 cups (720 ml) beef broth","1 tbsp soy sauce","1 tsp dried thyme","2 bay leaves","4 carrots, cut into 5 cm (2 in) pieces","700 g (1½ lb) potatoes, cut into large chunks","2 tbsp flour mixed with 3 tbsp cold water, for gravy"],
  byo:{intro:"This is a template for any big-pot braise. Keep the method (brown, add liquid, cook low and slow) and change what goes in.",ideas:[
   ["Meat","Chuck roast is classic and cheap. Beef short ribs, lamb shoulder, or bone-in chicken thighs (cook only 1 hr) also work."],
   ["Vegetables","Any root vegetables: parsnips, turnips, sweet potato, celery, mushrooms. Add soft vegetables like green beans in the last 20 min."],
   ["Flavors","A spoon of mustard, a few dried mushrooms, smoked paprika, rosemary, or a splash of balsamic vinegar in the broth."],
   ["Techniques","Slow cooker: brown the meat, then cook everything on low 8 hr. Leftovers make great sandwiches, tacos, or hash."]]},
  steps:[
   {name:"Season and brown",desc:"Heat the oven to 300°F (150°C). Pat the beef dry and season with the salt and pepper. Heat the oil in a large oven-safe pot (Dutch oven) over medium-high heat and brown the beef well, 4 min per side. Move it to a plate.",min:10},
   {name:"Build the pot",desc:"Lower to medium and cook the onions 4 min. Stir in the garlic and tomato paste for 1 min, then add the broth, soy sauce, thyme, and bay leaves, scraping up the browned bits. Put the beef back in.",min:6},
   {name:"Braise",desc:"Cover and move the pot to the oven. Cook 2 hours without opening it.",min:120},
   {name:"Add the vegetables",desc:"Take the pot out carefully (it's very hot), add the carrots and potatoes around the beef, cover, and cook 1 hour more, until the beef shreds easily with a fork.",min:60},
   {name:"Make the gravy",desc:"Move the beef and vegetables to a platter. Set the pot over medium heat on the stove, remove the bay leaves, and whisk in the flour-water mix. Simmer 3 min until thick. Taste for salt, then pour over the beef.",min:5}]},
 {id:"chicken-pot-pie",title:"Chicken Pot Pie with Biscuit Top",cuisine:"American",diet:["halal"],serves:6,cost:2.25,meal:["dinner"],tags:["oven","dumplings"],
  desc:"Chunks of chicken and vegetables in a creamy, savory sauce, baked under golden biscuits. Cozy comfort food made easier with frozen vegetables and canned biscuits.",
  pantry:["chicken","butter","onion","flour","broth","milk","frozen vegetables","biscuits","thyme"],
  ingredients:["4 tbsp butter","1 onion, diced","2 celery stalks, diced","⅓ cup (40 g) flour","2 cups (480 ml) chicken broth","1 cup (240 ml) milk","1 tsp dried thyme","1 tsp salt","½ tsp pepper","3 cups cooked chicken, shredded (a rotisserie chicken or leftovers; halal-certified to keep it halal)","2 cups (300 g) frozen peas and carrots","1 can (8 biscuits) refrigerated biscuit dough, or 1 sheet puff pastry"],
  steps:[
   {name:"Soften the vegetables",desc:"Heat the oven to 400°F (200°C). Melt the butter in a large oven-safe skillet or pot over medium heat. Cook the onion and celery 5 min until soft.",min:6},
   {name:"Make the sauce",desc:"Sprinkle in the flour and stir 1 min. Slowly whisk in the broth, then the milk, so no lumps form. Add the thyme, salt, and pepper and simmer, stirring, until thick like gravy, about 4 min.",min:6},
   {name:"Add the filling",desc:"Stir in the chicken and frozen vegetables and heat 2 min. Taste for salt. (No oven-safe pan? Pour it into a 23 × 33 cm / 9 × 13 in baking dish.)",min:3,timer:false},
   {name:"Top and bake",desc:"Arrange the biscuits on top of the filling, close together. Bake until the biscuits are golden and cooked through and the filling bubbles at the edges, 20–25 min.",min:22},
   {name:"Rest",desc:"Rest 10 min so the sauce thickens before serving.",min:10}]},
 {id:"spaghetti-meatballs",title:"Spaghetti and Meatballs",cuisine:"American",diet:["halal"],serves:5,cost:2.25,meal:["dinner"],tags:["pasta","oven"],
  desc:"The Italian-American Sunday classic: tender baked beef meatballs simmered in a garlicky tomato sauce and served over spaghetti with parmesan. Make a double batch of meatballs and freeze half.",
  pantry:["ground beef","breadcrumbs","eggs","parmesan","garlic","crushed tomatoes","onion","spaghetti","basil"],
  ingredients:["450 g (1 lb) ground beef (halal-certified to keep it halal)","½ cup (30 g) breadcrumbs","¼ cup (60 ml) milk","1 egg","½ cup (40 g) grated parmesan, plus more to serve","3 garlic cloves, minced, divided","1 tsp dried Italian seasoning","1¼ tsp salt, divided","2 tbsp olive oil","1 onion, diced","1 can (800 g / 28 oz) crushed tomatoes","½ tsp sugar","Pinch of red pepper flakes","450 g (1 lb) spaghetti","Fresh basil, to serve (optional)"],
  steps:[
   {name:"Mix and roll the meatballs",desc:"Heat the oven to 425°F (220°C). In a bowl, soak the breadcrumbs in the milk 2 min, then mix in the egg, parmesan, 1 minced garlic clove, Italian seasoning, and ¾ tsp salt. Add the beef and mix gently. Roll into 16–18 balls (about 4 cm / 1½ in) and set them on an oiled sheet pan.",min:10,timer:false},
   {name:"Bake the meatballs",desc:"Bake until browned, 15 min. They'll finish cooking in the sauce. Meanwhile, start the sauce and put a big pot of salted water on to boil.",min:15},
   {name:"Make the sauce",desc:"In a large pot over medium heat, cook the onion in the olive oil 5 min. Add the remaining garlic and pepper flakes for 30 seconds, then the tomatoes, sugar, and ½ tsp salt. Simmer gently while the meatballs bake.",min:6},
   {name:"Simmer together",desc:"Add the baked meatballs to the sauce, cover, and simmer 15 min. Meanwhile, cook the spaghetti until al dente, about 9–10 min, and drain.",min:15},
   {name:"Serve",desc:"Serve the spaghetti topped with sauce, meatballs, parmesan, and basil.",min:2,timer:false}]},
 {id:"fridge-soup",title:"Big-Pot Clean-Out-the-Fridge Soup",cuisine:"American",diet:["vegan","vegetarian","halal","glutenfree"],serves:6,cost:1.25,meal:["dinner","lunch"],tags:["soup","onepot"],
  desc:"A hearty vegetable soup made the way many families do it: start with onion, carrot, and celery, add broth, tomatoes, and beans, then toss in whatever vegetables, grains, or leftovers need using up. It makes a big pot and tastes even better the next day.",
  pantry:["onion","carrots","celery","garlic","diced tomatoes","broth","beans","potatoes","italian seasoning"],
  ingredients:["2 tbsp oil","1 onion, diced","2 carrots, diced","2 celery stalks, diced","3 garlic cloves, minced","1 tsp Italian seasoning or dried thyme","1 can (400 g / 14.5 oz) diced tomatoes","8 cups (2 L) vegetable broth","1 large potato, diced","1 can (400 g / 15 oz) white or kidney beans, drained","3–4 cups chopped vegetables you have (see ideas)","1 tsp salt, then more to taste","½ tsp pepper","1 tbsp lemon juice or vinegar"],
  byo:{intro:"Keep the base (onion, carrot, celery, broth, tomatoes) and use whatever you have for the rest. Add things in this order so nothing gets mushy.",ideas:[
   ["Hard vegetables (add with the potato)","Carrots, parsnips, sweet potato, butternut squash, cabbage, green beans."],
   ["Soft vegetables (last 8 min)","Zucchini, corn, peas, broccoli, spinach or kale, frozen mixed vegetables."],
   ["Protein","Beans or lentils, leftover chicken or beef, cooked sausage, or small meatballs. Raw meat: brown it first in step 1."],
   ["Starch","A handful of small pasta, rice, or barley (add with the potato and add 1 extra cup of water), or serve with bread."],
   ["Techniques","A parmesan rind, a spoon of pesto, or a splash of soy sauce adds depth. Freeze leftovers in portions for up to 3 months."]]},
  steps:[
   {name:"Cook the base",desc:"Heat the oil in a large pot over medium heat. Add the onion, carrot, and celery and cook until soft, about 8 min. Add the garlic and Italian seasoning for 1 min.",min:9},
   {name:"Add broth and hard vegetables",desc:"Add the tomatoes, broth, potato, and any hard vegetables, grains, or pasta. Bring to a boil, then lower to a simmer.",min:8},
   {name:"Simmer",desc:"Simmer partly covered until the potatoes are tender, about 15 min.",min:15},
   {name:"Add soft vegetables and beans",desc:"Stir in the beans and any soft vegetables or cooked meat. Simmer 8 min more, until everything is tender.",min:8},
   {name:"Season and serve",desc:"Add the salt, pepper, and lemon juice. Taste and add more salt if it tastes flat; soup usually needs more than you think. Serve with bread.",min:2,timer:false}]},
 {id:"beef-stew",title:"Hearty Beef Stew",cuisine:"American",diet:["halal"],serves:6,cost:3.00,meal:["dinner"],tags:["stew","onepot"],
  desc:"Chunks of beef simmered low and slow with potatoes, carrots, and onion in a thick, savory brown gravy. A winter staple that makes a big pot and freezes well.",
  pantry:["beef stew meat","flour","onion","garlic","tomato paste","broth","potatoes","carrots","thyme","bay leaves","peas"],
  ingredients:["900 g (2 lb) beef chuck, cut into 4 cm (1½ in) cubes (halal-certified to keep it halal)","3 tbsp flour","1½ tsp salt","½ tsp pepper","3 tbsp oil, divided","1 onion, diced","3 garlic cloves, minced","2 tbsp tomato paste","4 cups (1 L) beef broth","1 tbsp soy sauce","1 tsp dried thyme","2 bay leaves","3 carrots, sliced 2 cm (¾ in) thick","500 g (1 lb) potatoes, cut into 3 cm (1 in) cubes","1 cup frozen peas"],
  steps:[
   {name:"Coat and brown the beef",desc:"Toss the beef with the flour, salt, and pepper. Heat 2 tbsp oil in a large heavy pot over medium-high heat. Brown the beef in 2 batches, 5 min per batch, turning so each side gets dark. Don't crowd the pot, or it steams instead of browning. Move it to a plate.",min:10},
   {name:"Cook the onion",desc:"Add the remaining 1 tbsp oil and the onion and cook 4 min, scraping up the brown bits. Stir in the garlic and tomato paste for 1 min.",min:5},
   {name:"Simmer the beef",desc:"Add the broth, soy sauce, thyme, bay leaves, and beef. Bring to a boil, then cover and simmer on low for 1 hour 15 min, stirring now and then.",min:75},
   {name:"Add the vegetables",desc:"Add the carrots and potatoes, cover, and simmer 35 min more, until the beef and vegetables are tender.",min:35},
   {name:"Finish",desc:"Stir in the peas and cook 3 min. Remove the bay leaves and taste for salt. Serve with bread or biscuits.",min:3,timer:false}]},
 {id:"baked-potato-bar",title:"Build-Your-Own Baked Potato Bar",cuisine:"American",diet:["vegetarian","halal","glutenfree"],serves:4,cost:1.25,meal:["dinner","lunch"],tags:["oven"],
  desc:"Fluffy oven-baked russet potatoes with crispy, salty skins, split open and loaded with your favorite toppings. Set the toppings out and let everyone build their own. A cheap, filling dinner.",
  pantry:["potatoes","butter","sour cream","cheese","green onion","broccoli"],
  ingredients:["4 large russet potatoes","1 tbsp oil","1 tsp coarse salt","4 tbsp butter","½ cup sour cream","1 cup (100 g) shredded cheddar cheese","2 green onions, sliced","2 cups broccoli florets, steamed (optional)"],
  byo:{intro:"The potato is the base. Set out a few toppings and everyone builds their own.",ideas:[
   ["Classic","Butter, sour cream, cheddar, green onion, turkey or beef bacon bits."],
   ["Make it a meal","Leftover chili, pulled chicken, taco meat, or black beans with salsa."],
   ["Vegetables","Steamed broccoli with cheese sauce, sautéed mushrooms, corn, roasted peppers."],
   ["Techniques","Short on time? Microwave each pricked potato 5 min, flip, microwave 3–5 min more, then crisp in the hot oven 10 min. Sweet potatoes bake the same way."]]},
  steps:[
   {name:"Prep the potatoes",desc:"Heat the oven to 425°F (220°C). Scrub the potatoes, dry them well, and poke each one 6–8 times with a fork so steam can escape. Rub with the oil and sprinkle with the salt.",min:5,timer:false},
   {name:"Bake",desc:"Bake directly on the oven rack until a knife slides into the center with no resistance and the skin is crispy, 50–60 min.",min:55},
   {name:"Prep toppings",desc:"While the potatoes bake, steam the broccoli, shred the cheese, slice the green onions, and set out the toppings in bowls.",min:10,timer:false},
   {name:"Split and fluff",desc:"Cut a line across the top of each potato and squeeze the ends toward the middle so it opens up. Fluff the inside with a fork, add a pat of butter and a pinch of salt, and load it up.",min:3,timer:false}]},
 {id:"bbq-pulled-chicken",title:"BBQ Pulled Chicken Sandwiches",cuisine:"American",diet:["halal"],serves:6,cost:2.25,meal:["dinner","lunch"],tags:["sandwich"],
  desc:"Chicken thighs simmered in smoky homemade barbecue sauce until tender enough to shred, piled onto soft buns with crunchy coleslaw. Tastes like slow-smoked barbecue, but it's done on the stove in under an hour.",
  pantry:["chicken thighs","ketchup","brown sugar","vinegar","smoked paprika","garlic powder","onion","buns","coleslaw"],
  ingredients:["900 g (2 lb) boneless, skinless chicken thighs (halal-certified to keep it halal)","1 tsp salt","1 tbsp oil","1 onion, finely diced","Sauce: 1 cup ketchup, ¼ cup brown sugar, 3 tbsp apple cider vinegar, 1 tbsp mustard, 2 tsp smoked paprika, 1 tsp garlic powder, ½ tsp pepper, ½ cup (120 ml) water","6 burger buns","2 cups coleslaw mix plus 3 tbsp mayo and 1 tsp vinegar, or store-bought coleslaw"],
  steps:[
   {name:"Brown the chicken",desc:"Season the chicken with the salt. Heat the oil in a large pot over medium-high heat and brown the chicken 3 min per side. Move it to a plate.",min:6},
   {name:"Make the sauce",desc:"Lower to medium, cook the onion 4 min, then stir in all the sauce ingredients, scraping up the browned bits.",min:5},
   {name:"Simmer",desc:"Return the chicken to the pot, cover, and simmer on low until very tender, about 30 min. Turn the pieces halfway through. Meanwhile, toss the coleslaw mix with the mayo and vinegar.",min:30},
   {name:"Shred",desc:"Shred the chicken right in the pot with two forks. Simmer uncovered 5 min so the sauce thickens and coats the meat.",min:6,timer:false},
   {name:"Serve",desc:"Toast the buns if you like, pile on the chicken, and top with coleslaw.",min:3,timer:false}]},
 {id:"chicken-noodle-soup",title:"Chicken Noodle Soup",cuisine:"American",diet:["halal"],serves:6,cost:1.75,meal:["lunch","dinner"],tags:["soup","noodles","onepot"],
  desc:"Homemade chicken soup with tender chicken, carrots, celery, and egg noodles in a golden, herby broth. The classic sick-day comfort food, and much better than the can.",
  pantry:["chicken thighs","onion","carrots","celery","garlic","broth","egg noodles","thyme","bay leaves","parsley"],
  ingredients:["2 tbsp butter or oil","1 onion, diced","3 carrots, sliced","3 celery stalks, sliced","3 garlic cloves, minced","10 cups (2.4 L) chicken broth","680 g (1½ lb) boneless chicken thighs or breasts (halal-certified to keep it halal)","1 tsp dried thyme","2 bay leaves","1 tsp salt, then more to taste","½ tsp pepper","170 g (6 oz) wide egg noodles","2 tbsp chopped parsley","1 tbsp lemon juice"],
  steps:[
   {name:"Soften the vegetables",desc:"Melt the butter in a large pot over medium heat. Cook the onion, carrots, and celery until soft, about 7 min. Add the garlic for 1 min.",min:8},
   {name:"Poach the chicken",desc:"Add the broth, chicken, thyme, bay leaves, salt, and pepper. Bring to a boil, then lower to a gentle simmer and cook until the chicken is cooked through, with no pink when you cut the thickest piece, about 20 min.",min:20},
   {name:"Shred the chicken",desc:"Lift the chicken out onto a board and shred it with two forks. Keep the soup simmering.",min:4,timer:false},
   {name:"Cook the noodles",desc:"Add the noodles to the simmering soup and cook until tender, about 7 min (check the package).",min:7},
   {name:"Finish",desc:"Stir the chicken back in with the parsley and lemon juice. Remove the bay leaves and taste for salt. Noodles soak up broth as it sits; add a splash of water to leftovers.",min:2,timer:false}]},
 {id:"roast-vegetables",title:"Roast Any Vegetable",cuisine:"American",diet:["vegan","vegetarian","halal","glutenfree"],serves:4,cost:1.00,meal:["side","dinner"],tags:["oven","sheetpan"],
  desc:"The one method that makes almost any vegetable taste great: tossed with oil and salt and roasted in a hot oven until browned and sweet at the edges. Pick your vegetable and the timer matches.",
  pantry:["vegetables","olive oil","garlic powder","salt","pepper"],
  ingredients:["700 g (1½ lb) of one vegetable, or a mix that roasts in the same time","2 tbsp olive or vegetable oil","¾ tsp salt","¼ tsp pepper","½ tsp garlic powder (optional)","½ lemon, to finish (optional)"],
  byo:{intro:"Start with plain roasted vegetables, then finish them however you like.",ideas:[
   ["Finishes","Lemon, grated parmesan, a drizzle of honey or maple syrup, or a spoon of pesto."],
   ["Spices","Smoked paprika, cumin, chili flakes, or dried Italian herbs, tossed in with the oil."]]},
  choose:[{id:"veg",label:"Which vegetable are you roasting?",pick:1,options:[
   {label:"Asparagus or green beans",note:"trim the woody ends. Roasts fast."},
   {label:"Broccoli or cauliflower",note:"cut into bite-size florets with a flat side for browning."},
   {label:"Brussels sprouts",note:"trim and halve, and roast cut-side down."},
   {label:"Potatoes or carrots",note:"cut into 2–3 cm (1 in) chunks."},
   {label:"Sweet potato or squash",note:"peel squash, then cut into 2–3 cm (1 in) cubes."}]}],
  steps:[
   {name:"Heat the oven",desc:"Heat the oven to 425°F (220°C) with a rack in the middle. Put the empty sheet pan in while it heats; a hot pan browns vegetables better.",min:10},
   {name:"Cut and season",desc:"Cut the vegetables into even pieces so they cook at the same speed. Toss in a bowl with the oil, salt, pepper, and garlic powder until every piece is shiny.",min:6,timer:false},
   {name:"Roast",desc:"Carefully spread the vegetables on the hot pan in a single layer with space between them (crowded vegetables steam instead of browning). Roast, flipping once halfway, until tender and browned at the edges.",min:22,by:"veg",mins:[12,22,25,32,35]},
   {name:"Finish",desc:"Taste and add salt if needed. Finish with a squeeze of lemon if you like.",min:1,timer:false}]},
 {id:"buffalo-wings",title:"Oven-Baked Buffalo Wings",cuisine:"American",diet:["halal","glutenfree"],serves:4,cost:3.00,meal:["snack","dinner"],tags:["oven"],
  desc:"Game-day chicken wings baked until crackly-crisp (the secret is baking powder), then tossed in buttery, tangy hot sauce. Served with celery, carrots, and ranch or blue cheese dip.",
  pantry:["chicken wings","baking powder","hot sauce","butter","celery","carrots","ranch"],
  ingredients:["1.4 kg (3 lb) chicken wings, split into flats and drumettes (halal-certified to keep it halal)","1 tbsp baking powder (not baking soda)","1 tsp salt","½ cup (120 ml) hot sauce (Frank's RedHot is the classic)","4 tbsp butter","1 tsp honey (optional)","Celery and carrot sticks, and ranch or blue cheese dressing, to serve"],
  steps:[
   {name:"Dry and coat",desc:"Heat the oven to 425°F (220°C). Put a wire rack on a foil-lined sheet pan if you have one. Pat the wings very dry with paper towels, then toss with the baking powder and salt until evenly coated.",min:6,timer:false},
   {name:"Bake the first side",desc:"Spread the wings on the rack (or pan) in a single layer with space between them. Bake 25 min.",min:25},
   {name:"Flip and crisp",desc:"Flip each wing with tongs and bake 20 min more, until deep golden and crispy. Cut into one big wing: the meat by the bone should have no pink (175°F / 80°C).",min:20},
   {name:"Make the sauce",desc:"While the wings finish, melt the butter in a small pot with the hot sauce and honey, whisking until smooth.",min:3,timer:false},
   {name:"Toss and serve",desc:"Put the hot wings in a big bowl, pour the sauce over, and toss until coated. Serve right away with celery, carrots, and dressing.",min:2,timer:false}]},
 {id:"chocolate-chip-cookies",title:"Chocolate Chip Cookies",cuisine:"American",diet:["vegetarian","halal"],serves:24,cost:0.25,meal:["dessert"],tags:["sweets","oven"],
  desc:"Classic American cookies with crisp golden edges, soft chewy centers, and pockets of melted chocolate. Made with melted butter, so no mixer is needed.",
  pantry:["butter","brown sugar","sugar","eggs","vanilla","flour","baking soda","chocolate chips"],
  ingredients:["¾ cup (170 g) butter, melted and slightly cooled","1 cup (200 g) packed brown sugar","¼ cup (50 g) white sugar","1 egg plus 1 egg yolk","2 tsp vanilla extract","2 cups (250 g) all-purpose flour","1 tsp baking soda","½ tsp salt","1½ cups (255 g) chocolate chips"],
  steps:[
   {name:"Mix the wet ingredients",desc:"Heat the oven to 350°F (175°C) and line 2 sheet pans with parchment. In a large bowl, whisk the melted butter with both sugars until smooth, then whisk in the egg, yolk, and vanilla until glossy, about 1 min.",min:5,timer:false},
   {name:"Add the dry ingredients",desc:"Add the flour, baking soda, and salt and stir with a spatula until no dry flour remains. Stir in the chocolate chips.",min:3,timer:false},
   {name:"Chill the dough",desc:"Chill the dough 15 min (or up to 3 days) so the cookies don't spread too thin.",min:15},
   {name:"Bake",desc:"Scoop 2-tbsp balls of dough onto the pans, 5 cm (2 in) apart. Bake one pan at a time until the edges are golden but the centers still look a little underdone, 10–12 min.",min:11},
   {name:"Cool",desc:"Cool on the pan 5 min (they firm up as they cool), then move to a rack. Bake the second pan.",min:5}]},
 {id:"banana-bread",title:"Banana Bread",cuisine:"American",diet:["vegetarian","halal"],serves:10,cost:0.50,meal:["dessert","breakfast"],tags:["sweets","bread","oven"],
  desc:"A moist, tender loaf sweetened with very ripe bananas, with a hint of cinnamon and a golden, crackly top. The best way to use up spotty brown bananas, and one bowl is all you need.",
  pantry:["bananas","butter","brown sugar","eggs","vanilla","flour","baking soda","cinnamon"],
  ingredients:["3 very ripe bananas (brown spots are good)","⅓ cup (75 g) butter, melted","½ cup (100 g) brown sugar","1 egg","1 tsp vanilla extract","1 tsp baking soda","½ tsp ground cinnamon","Pinch of salt","1½ cups (190 g) all-purpose flour","½ cup chopped walnuts or chocolate chips (optional)"],
  steps:[
   {name:"Prep the pan",desc:"Heat the oven to 350°F (175°C). Grease a 23 × 13 cm (9 × 5 in) loaf pan with butter or oil.",min:3,timer:false},
   {name:"Mix the batter",desc:"In a large bowl, mash the bananas with a fork until mostly smooth. Stir in the melted butter, then the brown sugar, egg, and vanilla. Sprinkle the baking soda, cinnamon, and salt over the top and stir in. Add the flour and stir just until no dry flour remains (lumps are fine). Fold in nuts or chips.",min:6,timer:false},
   {name:"Bake",desc:"Pour into the pan and bake until a toothpick poked into the center comes out clean or with a few moist crumbs, 55–65 min. If the top browns too fast, cover it loosely with foil after 40 min.",min:60},
   {name:"Cool",desc:"Cool in the pan 10 min, then turn out onto a rack. Slice once it's mostly cool, or it crumbles.",min:15}]},
 {id:"southern-fried-chicken",title:"Buttermilk Fried Chicken",cuisine:"Southern U.S.",diet:["halal"],serves:4,cost:2.50,meal:["dinner"],tags:["fried"],
  desc:"Bone-in chicken soaked in tangy buttermilk, coated in seasoned flour, and fried until shatteringly crisp and juicy inside. A Southern Sunday dinner classic, served with biscuits, greens, or mashed potatoes.",
  pantry:["chicken","buttermilk","flour","paprika","garlic powder","cayenne","oil"],
  ingredients:["1.4 kg (3 lb) bone-in chicken pieces (thighs and drumsticks are easiest; halal-certified to keep it halal)","2 cups (480 ml) buttermilk (or 2 cups milk plus 2 tbsp lemon juice, rested 5 min)","2½ tsp salt, divided","2 cups (250 g) all-purpose flour","1 tbsp paprika","2 tsp garlic powder","1 tsp black pepper","½ tsp cayenne","About 4 cups (1 L) vegetable or peanut oil, for frying"],
  steps:[
   {name:"Soak in buttermilk",desc:"Stir 1 tsp salt into the buttermilk and add the chicken. Soak in the fridge at least 1 hour (up to overnight). It makes the chicken tender and helps the coating stick.",min:60,prep:true},
   {name:"Season the flour",desc:"In a large bowl, whisk the flour, paprika, garlic powder, pepper, cayenne, and 1½ tsp salt. Drizzle in 3 tbsp of the buttermilk and rub it in with your fingers; the little clumps become extra-crunchy bits.",min:4,timer:false},
   {name:"Heat the oil",desc:"Pour oil into a large heavy pot or deep skillet to 3 cm (1¼ in) deep. Heat over medium-high to 325°F (165°C). No thermometer? A pinch of flour should sizzle right away but not burn. Set a rack over a sheet pan nearby.",min:10,timer:false},
   {name:"Coat the chicken",desc:"Lift each piece out of the buttermilk, let the extra drip off, and press it firmly into the flour on all sides. Rest the coated pieces on a plate 5 min so the coating sets.",min:6,timer:false},
   {name:"Fry",desc:"Carefully lay half the chicken in the oil, away from you. Fry, turning every 3–4 min, until deep golden and it reads 175°F (80°C) near the bone, about 12–15 min. No thermometer? Cut into one piece near the bone: the juices should run clear with no pink. Keep the oil bubbling steadily but not smoking. Drain on the rack and fry the second batch.",min:28},
   {name:"Rest",desc:"Rest 5 min before serving; it stays crispy on the rack.",min:5}]},
 {id:"biscuits-gravy",title:"Biscuits and Sausage Gravy",cuisine:"Southern U.S.",diet:["halal"],serves:4,cost:1.50,meal:["breakfast"],tags:["bread","oven"],
  desc:"Tall, flaky buttermilk biscuits split open and smothered in a thick, peppery cream gravy full of crumbled breakfast sausage. A Southern breakfast that keeps you full all morning. This version uses turkey or beef sausage.",
  pantry:["flour","baking powder","butter","buttermilk","breakfast sausage","milk","pepper"],
  ingredients:["2 cups (250 g) all-purpose flour","1 tbsp baking powder","½ tsp baking soda","1 tsp salt, divided","½ cup (113 g) cold butter, cut into cubes","¾ cup (180 ml) cold buttermilk","340 g (12 oz) turkey or beef breakfast sausage (pork is traditional; turkey or beef keeps it halal)","3 tbsp flour, for the gravy","2½ cups (600 ml) milk","1 tsp black pepper, plus more to taste"],
  steps:[
   {name:"Make the biscuit dough",desc:"Heat the oven to 450°F (230°C). In a bowl, whisk the flour, baking powder, baking soda, and ½ tsp salt. Rub in the cold butter with your fingertips until it looks like coarse crumbs with some pea-size pieces. Stir in the buttermilk with a fork just until it comes together.",min:6,timer:false},
   {name:"Fold and cut",desc:"Turn the dough onto a floured counter and pat it into a rectangle. Fold it in thirds like a letter, pat it out again, and repeat twice; this makes flaky layers. Pat 2.5 cm (1 in) thick and cut 8 biscuits with a glass, pressing straight down without twisting. Put them on a sheet pan, touching.",min:6,timer:false},
   {name:"Bake the biscuits",desc:"Bake until tall and golden, 12–14 min. Start the gravy while they bake.",min:13},
   {name:"Brown the sausage",desc:"In a large skillet over medium heat, cook the sausage, breaking it into small crumbles, until browned with no pink left, about 6 min. Leave the fat in the pan (add 1 tbsp butter if it looks dry).",min:6},
   {name:"Make the gravy",desc:"Sprinkle the 3 tbsp flour over the sausage and stir 1 min. Slowly pour in the milk, stirring, and simmer until thick and creamy, 4–5 min. Season with the pepper and ½ tsp salt. Split the biscuits and spoon the gravy over.",min:6}]},
 {id:"skillet-cornbread",title:"Skillet Cornbread",cuisine:"Southern U.S.",diet:["vegetarian","halal"],serves:8,cost:0.40,meal:["side"],tags:["bread","oven"],
  desc:"Golden cornbread baked in a sizzling hot skillet for a crunchy crust and a tender, slightly sweet crumb. The classic partner for chili, greens, beans, and barbecue.",
  pantry:["cornmeal","flour","sugar","baking powder","buttermilk","eggs","butter"],
  ingredients:["1 cup (150 g) yellow cornmeal","1 cup (125 g) all-purpose flour","2 tbsp sugar (or up to ¼ cup for sweeter)","2 tsp baking powder","½ tsp baking soda","¾ tsp salt","1¼ cups (300 ml) buttermilk","2 eggs","5 tbsp butter, divided"],
  steps:[
   {name:"Heat the skillet",desc:"Put a 25 cm (10 in) cast-iron skillet (or an 20 × 20 cm / 8 × 8 in pan) in the oven and heat it to 425°F (220°C).",min:10},
   {name:"Mix the batter",desc:"In a bowl, whisk the cornmeal, flour, sugar, baking powder, baking soda, and salt. In another bowl, whisk the buttermilk and eggs. Melt 4 tbsp butter. Stir the wet into the dry, then the melted butter, just until combined.",min:5,timer:false},
   {name:"Bake",desc:"Carefully take out the hot skillet, add the last 1 tbsp butter and swirl it around (it should sizzle). Pour in the batter and bake until golden and a toothpick comes out clean, 18–22 min.",min:20},
   {name:"Cool and slice",desc:"Cool 5 min, then cut into wedges. Serve warm with butter or honey.",min:5}]},
 {id:"chicken-sausage-gumbo",title:"Chicken and Sausage Gumbo",cuisine:"Cajun",diet:["halal"],serves:8,cost:2.25,meal:["dinner"],tags:["stew","onepot"],
  desc:"Louisiana's famous big-pot stew: chicken and smoky sausage simmered in a rich, dark broth thickened with a roux (flour toasted in oil until chocolate-brown), with the \"holy trinity\" of onion, pepper, and celery. Served over rice; every family has its own version.",
  pantry:["chicken thighs","smoked sausage","flour","oil","onion","bell pepper","celery","garlic","broth","cajun seasoning","bay leaves","rice"],
  ingredients:["⅔ cup (160 ml) vegetable oil","⅔ cup (85 g) all-purpose flour","1 onion, diced","1 green bell pepper, diced","3 celery stalks, diced","4 garlic cloves, minced","8 cups (2 L) chicken broth","900 g (2 lb) boneless chicken thighs, cut into bite-size pieces (halal-certified to keep it halal)","340 g (12 oz) smoked beef or chicken sausage, sliced (andouille is pork)","2 tsp Cajun seasoning","1 tsp dried thyme","2 bay leaves","Salt, to taste","Sliced green onions, hot sauce, and cooked white rice, to serve"],
  byo:{intro:"Gumbo is a family pot: keep the roux and the trinity, and change what goes in.",ideas:[
   ["Proteins","Shrimp (add in the last 5 min), crab, leftover turkey after Thanksgiving, or okra and beans for a vegetable gumbo."],
   ["Thickeners","Sliced okra (add with the trinity) or a sprinkle of filé powder at the table, both traditional."],
   ["Techniques","The roux is the flavor: a peanut-butter color is mild, chocolate-brown is deep and nutty. Make the roux a day ahead, or brown flour dry in the oven to skip the stirring."]]},
  steps:[
   {name:"Prep everything first",desc:"The roux needs constant stirring, so dice the onion, pepper, celery, and garlic and keep them right next to the stove before you start.",min:10,timer:false},
   {name:"Make the roux",desc:"In a large heavy pot over medium heat, whisk the oil and flour together. Stir constantly with a wooden spoon, scraping the bottom, until it's the color of milk chocolate and smells nutty, 20–30 min. If you see black specks, it burned; start over.",min:25},
   {name:"Add the trinity",desc:"Add the onion, pepper, and celery all at once (it will sizzle and steam) and stir 5 min until soft. Add the garlic for 1 min.",min:6},
   {name:"Simmer",desc:"Slowly stir in the broth so no lumps form. Add the chicken, sausage, Cajun seasoning, thyme, and bay leaves. Bring to a boil, then simmer uncovered for 1 hour, stirring now and then and skimming off any oil on top.",min:60},
   {name:"Season and serve",desc:"Remove the bay leaves and taste; add salt if needed. Serve in bowls over rice with green onions and hot sauce.",min:3,timer:false}]},
 {id:"jambalaya",title:"Chicken and Shrimp Jambalaya",cuisine:"Cajun",diet:["halal"],seafood:true,serves:6,cost:2.75,meal:["dinner"],tags:["rice","onepot"],
  desc:"A one-pot Louisiana rice dish: rice cooked right in a spicy tomato broth with chicken, smoked sausage, shrimp, and the trinity of onion, pepper, and celery. Bold, smoky, and a little spicy.",
  pantry:["chicken thighs","smoked sausage","shrimp","onion","bell pepper","celery","garlic","diced tomatoes","rice","broth","cajun seasoning"],
  ingredients:["2 tbsp oil","340 g (12 oz) smoked beef or chicken sausage, sliced","450 g (1 lb) boneless chicken thighs, cut into bite-size pieces (halal-certified to keep it halal)","2 tsp Cajun seasoning, divided","1 onion, diced","1 green bell pepper, diced","2 celery stalks, diced","3 garlic cloves, minced","1 can (400 g / 14.5 oz) diced tomatoes","1½ cups (300 g) long-grain white rice","3 cups (720 ml) chicken broth","1 tsp dried thyme","2 bay leaves","225 g (½ lb) shrimp, peeled","2 green onions, sliced"],
  steps:[
   {name:"Brown the meats",desc:"Heat the oil in a large heavy pot over medium-high heat. Brown the sausage 4 min and move it to a plate. Toss the chicken with 1 tsp Cajun seasoning and brown it 5 min; add to the plate.",min:9},
   {name:"Cook the trinity",desc:"Cook the onion, pepper, and celery in the pot 5 min until soft. Add the garlic for 1 min.",min:6},
   {name:"Add the rice and liquid",desc:"Stir in the rice for 1 min, then add the tomatoes, broth, thyme, bay leaves, the rest of the Cajun seasoning, and the meats. Bring to a boil.",min:4,timer:false},
   {name:"Simmer covered",desc:"Cover tightly, turn the heat to low, and cook 20 min without lifting the lid.",min:20},
   {name:"Add the shrimp",desc:"Scatter the shrimp over the rice, cover again, and cook 6 min until pink. Turn off the heat and rest 5 min, then fluff, remove the bay leaves, and top with green onions.",min:11}]},
 {id:"shrimp-etouffee",title:"Shrimp Étouffée",cuisine:"Cajun",diet:["halal"],seafood:true,serves:4,cost:3.50,meal:["dinner"],tags:["stew"],
  desc:"Shrimp \"smothered\" (that's what étouffée means) in a thick, buttery, golden-brown sauce with the trinity, garlic, and Cajun spice, served over rice. Rich and comforting, and faster than gumbo.",
  pantry:["shrimp","butter","flour","onion","bell pepper","celery","garlic","broth","cajun seasoning","rice","green onion"],
  ingredients:["4 tbsp butter","¼ cup (30 g) flour","1 onion, diced","1 green bell pepper, diced","2 celery stalks, diced","3 garlic cloves, minced","1 tbsp tomato paste","2 cups (480 ml) seafood or chicken broth","1½ tsp Cajun seasoning","1 bay leaf","680 g (1½ lb) shrimp, peeled and deveined","Salt, to taste","Juice of ½ lemon","3 green onions, sliced","Cooked white rice, to serve"],
  steps:[
   {name:"Make a blond roux",desc:"Melt the butter in a large skillet over medium heat. Whisk in the flour and stir constantly until it's the color of peanut butter, about 8 min.",min:8},
   {name:"Cook the trinity",desc:"Add the onion, pepper, and celery and cook 6 min, stirring, until soft. Add the garlic and tomato paste for 1 min.",min:7},
   {name:"Simmer the sauce",desc:"Slowly stir in the broth, then add the Cajun seasoning and bay leaf. Simmer until thick like gravy, about 10 min.",min:10},
   {name:"Cook the shrimp",desc:"Add the shrimp and simmer 4–5 min, until pink and curled. Don't overcook or they turn rubbery.",min:5},
   {name:"Finish",desc:"Remove the bay leaf, stir in the lemon juice and most of the green onions, and taste for salt. Serve over rice with the rest of the green onions.",min:2,timer:false}]},
 {id:"blackened-catfish",title:"Blackened Catfish",cuisine:"Cajun",diet:["halal","glutenfree"],seafood:true,serves:4,cost:3.00,meal:["dinner"],tags:["grill"],
  desc:"Mild catfish fillets coated in a bold, smoky Cajun spice mix and seared in a very hot pan until the spices form a dark, crusty, flavorful coating (not burnt). Ready in 15 minutes; great with rice, coleslaw, or in tacos.",
  pantry:["catfish","paprika","garlic powder","onion powder","thyme","oregano","cayenne","butter","lemon"],
  ingredients:["4 catfish fillets (about 680 g / 1½ lb; tilapia or any firm white fish works)","Spice mix: 2 tsp paprika, 1 tsp garlic powder, 1 tsp onion powder, 1 tsp dried thyme, ½ tsp dried oregano, ½–1 tsp cayenne, 1 tsp salt, ½ tsp pepper","3 tbsp butter, melted","1 tbsp oil","Lemon wedges, to serve"],
  steps:[
   {name:"Season the fish",desc:"Mix the spice mix in a small bowl. Pat the fillets dry, brush both sides with melted butter, and press the spice mix on all over.",min:4,timer:false},
   {name:"Heat the pan",desc:"Heat a cast-iron skillet over high heat until very hot, about 4 min. Add the oil. Open a window and turn on the fan; this makes smoke.",min:4,timer:false},
   {name:"Sear",desc:"Lay the fillets in the pan and cook without moving 2–3 min until the bottom is dark and crusty. Flip and cook 2–3 min more, until the fish flakes easily with a fork.",min:5},
   {name:"Serve",desc:"Drizzle with any remaining butter and serve with lemon wedges.",min:1,timer:false}]}
);
